CREATE TABLE IF NOT EXISTS economic_activity_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES economic_entities(id) ON DELETE CASCADE, model_version text NOT NULL DEFAULT 'ECON-ACTIVITY-V1', operating_history_score numeric(6,2) NOT NULL DEFAULT 0, revenue_evidence_score numeric(6,2) NOT NULL DEFAULT 0, identity_score numeric(6,2) NOT NULL DEFAULT 0, asset_evidence_score numeric(6,2) NOT NULL DEFAULT 0, expense_visibility_score numeric(6,2) NOT NULL DEFAULT 0, continuity_score numeric(6,2) NOT NULL DEFAULT 0, risk_score numeric(6,2) NOT NULL DEFAULT 0, overall_score numeric(6,2) NOT NULL DEFAULT 0, state text NOT NULL DEFAULT 'insufficient_data', missing_evidence jsonb NOT NULL DEFAULT '[]'::jsonb, recommendations jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now());